from datetime import datetime, timedelta


class Appointment:
    def __init__(self, appointment_id: int, patient: str, doctor: str, start: datetime, end: datetime) -> None:
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.cancelled = False
        self.blocked = True


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: dict[int, Appointment] = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime, now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Appointment start time must be before end time.")

        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        if not self.is_free(doctor, start, end):
            raise ValueError(f"Doctor {doctor} is not available for the requested time slot.")

        appointment_id = self._next_id
        self._next_id += 1

        self._appointments[appointment_id] = Appointment(
            appointment_id=appointment_id,
            patient=patient,
            doctor=doctor,
            start=start,
            end=end
        )
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an appointment given its id and the current time."""
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")

        appointment = self._appointments[appointment_id]
        if appointment.cancelled:
            return

        appointment.cancelled = True
        # If cancelled at least 24 hours before the appointment start, free the slot.
        if (appointment.start - now) >= timedelta(hours=24):
            appointment.blocked = False
        else:
            appointment.blocked = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start time must be before end time.")

        for appt in self._appointments.values():
            if appt.doctor == doctor and appt.blocked:
                # Two intervals [start, end) and [appt.start, appt.end) overlap
                # if start < appt.end and end > appt.start. Touching endpoints do not overlap.
                if max(start, appt.start) < min(end, appt.end):
                    return False
        return True
